package io.netty.channel.uring;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * Verifies that the SQE field offset constants in {@link SubmissionQueue}
 * match the kernel's io_uring_sqe struct layout defined at:
 * https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/include/uapi/linux/io_uring.h
 *
 * Kernel struct layout (offsets in bytes):
 * <pre>
 *   0:  opcode        (u8)
 *   1:  flags         (u8)
 *   2:  ioprio        (u16)
 *   4:  fd            (s32)
 *   8:  off/addr2     (u64)
 *  16:  addr          (u64)
 *  24:  len           (u32)
 *  28:  rw_flags      (s32)
 *  32:  user_data     (u64)
 *  40:  buf_index     (u16)  -- union
 *  42:  buf_group     (u16)  -- union
 *  40:  addr3         (u32)  -- union, used for splice fd_in
 *  44:  personality   (u16)
 *  46:  __pad2        (u16)
 *  48:  __pad3[3]     (u64)
 * </pre>
 */
public class SubmissionQueueSqeOffsetTest {

    /**
     * The io_uring_sqe kernel struct places the union
     * { buf_index, buf_group, addr3 } at offset 40.
     * For SPLICE operations, the source file descriptor (fd_in)
     * is carried in the addr3 field of this union.
     * Therefore SQE_SPLICE_FD_IN must be 40, not 44.
     */
    @Test
    public void sqeSpliceFdInOffsetMustMatchKernelAddr3() throws Exception {
        try {
            Field field = SubmissionQueue.class.getDeclaredField("SQE_SPLICE_FD_IN");
        } catch (NoSuchFieldException e) {
            // Field does not exist on older code - nothing to verify.
            return;
        }
        Field field = SubmissionQueue.class.getDeclaredField("SQE_SPLICE_FD_IN");
        field.setAccessible(true);
        int actual = field.getInt(null);
        // The kernel struct places addr3 (used for splice fd_in) at offset 40.
        assertEquals(40, actual,
                "SQE_SPLICE_FD_IN must be 40 to match kernel io_uring_sqe::addr3 offset");
    }

    /**
     * buf_index (used for fixed buffer selection) is at offset 40.
     */
    @Test
    public void sqeFixedBufferOffsetMustMatchKernelBufIndex() throws Exception {
        try {
            Field field = SubmissionQueue.class.getDeclaredField("SQE_FIXED_BUFFER");
        } catch (NoSuchFieldException e) {
            // Field does not exist on older code - nothing to verify.
            return;
        }
        Field field = SubmissionQueue.class.getDeclaredField("SQE_FIXED_BUFFER");
        field.setAccessible(true);
        int actual = field.getInt(null);
        assertEquals(40, actual,
                "SQE_FIXED_BUFFER must be 40 to match kernel io_uring_sqe::buf_index offset");
    }

    /**
     * personality is at offset 44 in the kernel struct.
     */
    @Test
    public void sqePersonalityOffsetMustMatchKernelPersonality() throws Exception {
        try {
            Field field = SubmissionQueue.class.getDeclaredField("SQE_PERSONALITY");
        } catch (NoSuchFieldException e) {
            // Field does not exist on older code - nothing to verify.
            return;
        }
        Field field = SubmissionQueue.class.getDeclaredField("SQE_PERSONALITY");
        field.setAccessible(true);
        int actual = field.getInt(null);
        assertEquals(44, actual,
                "SQE_PERSONALITY must be 44 to match kernel io_uring_sqe::personality offset");
    }
}

