package io.netty.channel.uring;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * Tests for {@link IoUringIoOps} SPLICE operation field mapping.
 */
public class IoUringIoOpsSpliceTest {

    @Test
    public void spliceOpsFieldMapping() {
        // For IORING_OP_SPLICE, the kernel expects:
        //   sqe->off  (SQE_OFFSET_FIELD at offset 8)  to contain off_in
        //   sqe->addr (SQE_ADDRESS_FIELD at offset 16) to contain off_out
        //
        // SubmissionQueue.setData() writes:
        //   sqe+SQE_OFFSET_FIELD  <- offset    (from IoUringIoOps.offset())
        //   sqe+SQE_ADDRESS_FIELD <- bufferAddress (from IoUringIoOps.bufferAddress())
        //
        // Therefore, for a correct SPLICE submission:
        //   IoUringIoOps.offset()       must equal off_in
        //   IoUringIoOps.bufferAddress() must equal off_out
        //
        // See: https://github.com/axboe/liburing/blob/liburing-2.8/src/include/liburing/io_uring.h
        //   .off = (void *) off_in,
        //   .addr = (void *) off_out,
        int fdIn = 3, fdOut = 4;
        long offIn = 42L, offOut = 99L;
        int nbytes = 100;
        int spliceFlags = Native.SPLICE_F_MOVE;
        short data = 7;

        IoUringIoOps ops = IoUringIoOps.newSplice(fdIn, offIn, fdOut, offOut, nbytes, spliceFlags, data);

        // Verify the opcode is SPLICE
        assertEquals(Native.IORING_OP_SPLICE, ops.opcode());

        // The io_uring kernel ABI requires:
        //   sqe.off  = off_in  (input file offset)
        //   sqe.addr = off_out (output file offset)
        //
        // Since SubmissionQueue writes IoUringIoOps.offset() to sqe.off
        // and IoUringIoOps.bufferAddress() to sqe.addr,
        // we expect offset() == off_in and bufferAddress() == off_out.
        assertEquals(offIn, ops.offset(),
                "IoUringIoOps.offset() should be off_in so it lands in sqe.off for SPLICE");
        assertEquals(offOut, ops.bufferAddress(),
                "IoUringIoOps.bufferAddress() should be off_out so it lands in sqe.addr for SPLICE");

        // Verify fd and spliceFdIn
        assertEquals(fdOut, ops.fd());
        assertEquals(fdIn, ops.spliceFdIn());
    }
}

